policies.inbound:













                        application/json



                        unavailable

                    @{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", "invalid_web_search_filters"),
                                new JProperty("message", (string)context.Variables["web-search-validation-error"])
                            ))
                        ).ToString();
                    }



        @{
            var body = context.Request.Body.As<JObject>(preserveContent: true);
            var requiredDomains = new string[] {
                "youtube.com",
                "tiktok.com",
                "huggingface.co",
                "facebook.com",
                "x.ai",
                "spotify.com",
                "pinterest.com",
                "perplexity.ai",
                "netflix.com",
                "weebly.com",
                "repo.maven.apache.org"
            };
            foreach (var item in (JArray)body["tools"])
            {
                var tool = item as JObject;
                if (tool?["type"]?.Type != JTokenType.String || (string)tool["type"] != "web_search")
                {
                    continue;
                }
                var filters = tool["filters"] as JObject;
                if (filters == null)
                {
                    filters = new JObject();
                    tool["filters"] = filters;
                }
                var blocked = filters["blocked_domains"] as JArray;
                if (blocked == null)
                {
                    blocked = new JArray();
                    filters["blocked_domains"] = blocked;
                }
                foreach (var domain in requiredDomains)
                {
                    bool exists = false;
                    foreach (var existing in blocked)
                    {
                        if (string.Equals((string)existing, domain, StringComparison.OrdinalIgnoreCase))
                        {
                            exists = true;
                            break;
                        }
                    }
                    if (!exists)
                    {
                        blocked.Add(domain);
                    }
                }
            }
            return body.ToString(Newtonsoft.Json.Formatting.None);
        }







    @(context.RequestId.ToString())


{backend-routing}

set-variable.value:
@{
                    if (context.Response.StatusCode < 200 || context.Response.StatusCode >= 300)
                    {
                        return -1L;
                    }
                    var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
                    if (context.Response.Body == null) { return -1L; }
                    if (!string.Equals(contentType, "application/json", StringComparison.OrdinalIgnoreCase))
                    {
                        return -1L;
                    }
                    try
                    {
                        /* Only JSON responses are inspected. SSE returned before this read. */
                        var response = context.Response.Body.As<JObject>(preserveContent: true);
                        var status = (string)response["status"];
                        if (status != "completed" && status != "incomplete" && status != "failed") { return -1L; }
                        var output = response["output"] as JArray;
                        if (output == null) { return -1L; }
                        long total = 0;
                        foreach (var token in output)
                        {
                            var item = token as JObject;
                            if (item == null) { return -1L; }
                            if ((string)item["type"] != "web_search_call") { continue; }
                            if ((string)item["status"] != "completed") { return -1L; }
                            var action = item["action"] as JObject;
                            if (action == null) { return -1L; }
                            var actionType = (string)action["type"];
                            if (actionType == "open_page" || actionType == "find_in_page") { continue; }
                            if (actionType != "search") { return -1L; }
                            var queriesToken = action["queries"];
                            if (queriesToken != null && queriesToken.Type != JTokenType.Null)
                            {
                                var queries = queriesToken as JArray;
                                if (queries == null) { return -1L; }
                                foreach (var query in queries)
                                {
                                    if (query.Type != JTokenType.String || string.IsNullOrWhiteSpace((string)query)) { return -1L; }
                                }
                                /* query is often also present: it is not an additional search. */
                                total += queries.Count;
                            }
                            else if (action["query"]?.Type == JTokenType.String && !string.IsNullOrWhiteSpace((string)action["query"]))
                            {
                                total += 1;
                            }
                            else { return -1L; }
                        }
                        return total;
                    }
                    catch (Exception)
                    {
                        /* Accounting must not turn an otherwise valid backend response into a 500. */
                        return -1L;
                    }
                }
